SELECT apr10_second_emp_id
  FROM apr10_stamp
       INNER JOIN apr01_appr ON apr10_stamp_id = apr01_stamp_id
 WHERE apr01_appr_id = #{apprId}
   AND apr10_emp_id = #{personId}
 LIMIT 1

SELECT COUNT(*)
  FROM apr50_bookmark
 WHERE apr50_company_id = #{companyId}
   AND apr50_appr_id = #{apprId}
   AND ( apr50_person_id = #{personId} OR apr50_public_yn = 'true' )

SELECT COUNT(*)
  FROM apr42_comment
 WHERE apr42_appr_id = #{apprId}
   AND apr42_company_id = #{companyId}
